-- Queryopsy case database: UPI Fraud Desk
-- Source: data/samples/upi_placeholder.csv (PLACEHOLDER - synthetic)
-- Generated by pipeline/build.py - do not edit by hand.

-- UPI transactions with the fraud model's label (fraud_flag).
CREATE TABLE transactions (
  txn_id TEXT PRIMARY KEY,
  ts TEXT,
  txn_type TEXT,
  merchant_category TEXT,
  amount REAL,
  status TEXT,
  sender_age TEXT,
  sender_state TEXT,
  sender_bank TEXT REFERENCES banks(bank),
  receiver_bank TEXT REFERENCES banks(bank),
  device TEXT,
  network TEXT,
  fraud_flag INTEGER
);

-- Bank master.
CREATE TABLE banks (
  bank TEXT PRIMARY KEY,
  is_private INTEGER
);

